using System;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
public static class StairACollisionFinish {public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("T02_StairA_Art");var core=group.Find("VA_Core");var corridor=group.Find("T02_Corridor");foreach(float x in new[]{-1.76f,1.76f})foreach(float z in new[]{-3.08f,3.08f})Add(core,"Column_Collision_"+x+"_"+z,new Vector3(x,8,z),new Vector3(.14f,16,.14f));foreach(float x in new[]{-1.98f,1.98f})Add(corridor,"CartRail_Collision_"+x,new Vector3(x,.94f,6.883046f),new Vector3(.15f,.11f,12.566092f));Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{newColliders=6};}static void Add(Transform p,string n,Vector3 pos,Vector3 size){if(p.Find(n))return;var g=new GameObject(n);g.transform.SetParent(p,false);var c=g.AddComponent<BoxCollider>();c.center=pos;c.size=size;}}
